package com.shikshasetu.controller;

import com.shikshasetu.model.Student;import com.shikshasetu.model.PortalUser;import com.shikshasetu.model.PortalSession;import com.shikshasetu.portal.*;import com.shikshasetu.repo.*;import com.shikshasetu.service.PortalAuditService;import com.shikshasetu.service.RiskService;import com.shikshasetu.service.StudentTrendService;
import jakarta.validation.Valid;import org.springframework.data.domain.Sort;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/students") public class StudentController{
 private final StudentRepository students;private final RiskService riskService;private final StudentTrendService trendService;private final AcademicRecordRepository academicRecords;private final RiskAssessmentRepository riskAssessments;private final MentorFeedbackRepository mentorFeedback;private final ManualInterpretationRepository manualInterpretations;private final AiAssessmentRepository aiAssessments;private final PortalUserRepository portalUsers;private final PortalSessionRepository portalSessions;private final ChatInteractionRepository chatInteractions;private final StudentProgressRepository progress;private final PortalAuditService audit;
 public StudentController(StudentRepository s,RiskService r,StudentTrendService t,AcademicRecordRepository a,RiskAssessmentRepository ra,MentorFeedbackRepository m,ManualInterpretationRepository mi,AiAssessmentRepository ai,PortalUserRepository portalUsers,PortalSessionRepository portalSessions,ChatInteractionRepository chatInteractions,StudentProgressRepository progress,PortalAuditService audit){students=s;riskService=r;trendService=t;academicRecords=a;riskAssessments=ra;mentorFeedback=m;manualInterpretations=mi;aiAssessments=ai;this.portalUsers=portalUsers;this.portalSessions=portalSessions;this.chatInteractions=chatInteractions;this.progress=progress;this.audit=audit;}
 @PostMapping @Transactional public Student create(@Valid @RequestBody Student student){PortalPrincipal p=PortalAuthContext.require();if(p.institutionId()==null)throw new IllegalStateException("Institution context required");student.setId(null);student.setInstitutionId(p.institutionId());String code=student.getStudentCode()==null?"":student.getStudentCode().trim();if(students.existsByStudentCodeIgnoreCase(code))throw new IllegalArgumentException("A student with this Student ID already exists");student.setStudentCode(code);return students.save(student);}
 @GetMapping @Transactional(readOnly=true) public List<Student> all(){PortalPrincipal p=PortalAuthContext.require();if(p.isSuperAdmin())return students.findAll(Sort.by(Sort.Direction.ASC,"fullName"));if(p.isStudent())return students.findById(p.studentId()).map(List::of).orElseGet(List::of);return students.findAllByInstitutionId(p.institutionId(),Sort.by(Sort.Direction.ASC,"fullName"));}
 @GetMapping("/{id}") @Transactional(readOnly=true) public Student one(@PathVariable Long id){return requireStudent(id);}
 @PutMapping("/{id}") @Transactional public Student update(@PathVariable Long id,@Valid @RequestBody Student body){Student current=requireStudent(id);String code=body.getStudentCode()==null?"":body.getStudentCode().trim();students.findByStudentCodeIgnoreCase(code).ifPresent(existing->{if(!existing.getId().equals(id))throw new IllegalArgumentException("A different student already uses this Student ID");});current.setStudentCode(code);current.setFullName(body.getFullName());if(body.getEmail()!=null&&!body.getEmail().isBlank())current.setEmail(body.getEmail().trim());current.setAttendance(body.getAttendance());current.setInternalMarks(body.getInternalMarks());current.setAssignmentsCompleted(body.getAssignmentsCompleted());current.setPreviousFailures(body.getPreviousFailures());current.setAbsences(body.getAbsences());current.setAuditGroup(body.getAuditGroup());Student saved=students.save(current);List<PortalUser> linkedAccounts=portalUsers.findByStudentId(id);String newEmail=saved.getEmail();if(newEmail!=null&&!newEmail.isBlank()){for(PortalUser account:linkedAccounts){if(!newEmail.equalsIgnoreCase(account.getEmail())){portalUsers.findByEmailIgnoreCase(newEmail.trim()).filter(existing->!existing.getId().equals(account.getId())).ifPresent(existing->{throw new IllegalArgumentException("That email address is already used by another account");});account.setEmail(newEmail.trim().toLowerCase(Locale.ROOT));}account.setFullName(saved.getFullName());}portalUsers.saveAll(linkedAccounts);}else{for(PortalUser account:linkedAccounts)account.setFullName(saved.getFullName());portalUsers.saveAll(linkedAccounts);}audit.record("STUDENT_RECORD_UPDATED",id,"Administrator updated academic/profile fields; linked student account profile synchronized");return saved;}
 @DeleteMapping("/{id}") @Transactional public Map<String,String> delete(@PathVariable Long id){Student student=requireStudent(id);List<PortalUser> accounts=portalUsers.findByStudentId(id);for(PortalUser account:accounts){List<PortalSession> activeSessions=portalSessions.findByUserIdAndRevokedAtIsNull(account.getId());activeSessions.forEach(PortalSession::revoke);portalSessions.saveAll(activeSessions);account.setStudentId(null);account.setAccountStatus("SUSPENDED");portalUsers.save(account);}chatInteractions.deleteByStudentId(id);progress.deleteByStudentId(id);academicRecords.deleteByStudentId(id);riskAssessments.deleteByStudentId(id);mentorFeedback.deleteByStudentId(id);manualInterpretations.deleteByStudentId(id);aiAssessments.deleteByStudentId(id);audit.record("STUDENT_RECORD_DELETED",id,"Student record and linked account access were removed; associated progress and chat records deleted");students.delete(student);return Map.of("message","Student and associated records deleted; linked portal access suspended");}
 @PostMapping("/{id}/assess") public com.shikshasetu.dto.RiskAssessmentView assess(@PathVariable Long id){return riskService.assess(id);}
 @GetMapping("/{id}/risk-history") public List<com.shikshasetu.dto.RiskAssessmentView> riskHistory(@PathVariable Long id){return riskService.history(id);}
 @GetMapping("/{id}/early-warnings") public List<com.shikshasetu.dto.EarlyWarningView> earlyWarnings(@PathVariable Long id){requireStudent(id);return trendService.findWarnings(id);}
 private Student requireStudent(Long id){PortalPrincipal p=PortalAuthContext.require();return students.findById(id).filter(s->p.isSuperAdmin()||Objects.equals(s.getInstitutionId(),p.institutionId())).orElseThrow(()->new NoSuchElementException("Student not found"));}
}
